/// A minimal PDF reader used by the export tests.
///
/// A successfully written file is not proof of correct content, so the tests
/// parse the generated bytes and extract the text that a reader would show.
/// The parser understands exactly what the `pdf` package emits:
///
/// * indirect objects in the body (no cross-reference parsing),
/// * Flate-compressed streams,
/// * `/Type /Page` dictionaries with `/Contents` and inline or referenced
///   `/Resources`,
/// * `/ToUnicode` CMaps written as a `beginbfchar` list,
/// * content-stream operators `Tf`, `Tj`, `TJ`, `'`, `"`, `Td`, `TD`, `T*`, `ET`.
///
/// It is intentionally not a general-purpose PDF parser.
library;

import 'dart:typed_data';

import 'package:archive/archive.dart';

class _Literal {
  const _Literal(this.value);
  final String value;
}

class _Hex {
  const _Hex(this.hex);
  final String hex;
}

class _Name {
  const _Name(this.value);
  final String value;
}

class _Array {
  const _Array(this.items);
  final List<Object> items;
}

class _Num {
  const _Num(this.value);
  final double value;
}

class _Obj {
  const _Obj({required this.number, required this.body, required this.stream});

  final int number;

  /// The dictionary portion of the object, as a latin1 string.
  final String body;

  /// Raw (possibly compressed) stream bytes, when the object has one.
  final Uint8List? stream;
}

final _objectPattern = RegExp(r'(\d+)\s+0\s+obj([\s\S]*?)endobj');
final _streamPattern = RegExp(r'(?<!end)stream\r?\n');

List<_Obj> _parseObjects(Uint8List bytes) {
  final text = String.fromCharCodes(bytes);
  final objects = <_Obj>[];
  for (final match in _objectPattern.allMatches(text)) {
    final header = match.group(0)!;
    final bodyStart = match.start + header.indexOf('obj') + 3;
    final rawBody = match.group(2)!;
    final streamMatch = _streamPattern.firstMatch(rawBody);

    Uint8List? stream;
    if (streamMatch != null) {
      final dataStart = bodyStart + streamMatch.end;
      final endIndex = rawBody.indexOf('endstream', streamMatch.end);
      final dataEnd = endIndex < 0
          ? bodyStart + rawBody.length
          : bodyStart + endIndex;
      if (dataEnd > dataStart) stream = bytes.sublist(dataStart, dataEnd);
    }

    objects.add(
      _Obj(number: int.parse(match.group(1)!), body: rawBody, stream: stream),
    );
  }
  return objects;
}

/// Returns an object's stream decoded to text, or `null` when it has none.
String? _streamText(_Obj obj) {
  final data = obj.stream;
  if (data == null) return null;
  List<int> raw = data;
  if (obj.body.contains('/FlateDecode')) {
    try {
      raw = ZLibDecoder().decodeBytes(data);
    } on Object {
      raw = data;
    }
  }
  return String.fromCharCodes(raw);
}

/// Parses a `beginbfchar` CMap into code -> text.
Map<int, String> _parseCMap(String cmap) {
  final map = <int, String>{};
  for (final match in RegExp(
    r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>',
  ).allMatches(cmap)) {
    final code = int.parse(match.group(1)!, radix: 16);
    final hex = match.group(2)!;
    final buffer = StringBuffer();
    for (var i = 0; i + 4 <= hex.length; i += 4) {
      buffer.writeCharCode(int.parse(hex.substring(i, i + 4), radix: 16));
    }
    map[code] = buffer.toString();
  }
  return map;
}

/// Extracts every page's text from [bytes], in page order.
String extractPdfText(Uint8List bytes) {
  final objects = _parseObjects(bytes);
  final byNumber = {for (final obj in objects) obj.number: obj};

  final cmaps = <int, Map<int, String>>{};
  for (final obj in objects) {
    final ref = RegExp(r'/ToUnicode\s+(\d+)\s+0\s+R').firstMatch(obj.body);
    if (ref == null) continue;
    final target = byNumber[int.parse(ref.group(1)!)];
    if (target == null) continue;
    final text = _streamText(target);
    if (text != null) cmaps[obj.number] = _parseCMap(text);
  }

  final output = StringBuffer();
  for (final obj in objects) {
    if (!RegExp(r'/Type\s*/Page(?![s])').hasMatch(obj.body)) continue;
    final fonts = _pageFonts(obj, byNumber);
    final content = _contentText(obj, byNumber);
    if (content == null) continue;
    output
      ..write(_decodeContent(content, fonts, cmaps))
      ..write('\n');
  }
  return output.toString();
}

Map<String, int> _pageFonts(_Obj page, Map<int, _Obj> byNumber) {
  var source = page.body;
  final ref = RegExp(r'/Resources\s+(\d+)\s+0\s+R').firstMatch(page.body);
  if (ref != null) {
    final target = byNumber[int.parse(ref.group(1)!)];
    if (target != null) source = target.body;
  }
  final fontDict = RegExp(r'/Font\s*<<([\s\S]*?)>>').firstMatch(source);
  if (fontDict == null) return const {};
  return {
    for (final match in RegExp(
      r'/([A-Za-z0-9]+)\s+(\d+)\s+0\s+R',
    ).allMatches(fontDict.group(1)!))
      match.group(1)!: int.parse(match.group(2)!),
  };
}

String? _contentText(_Obj page, Map<int, _Obj> byNumber) {
  final single = RegExp(r'/Contents\s+(\d+)\s+0\s+R').firstMatch(page.body);
  if (single != null) {
    final target = byNumber[int.parse(single.group(1)!)];
    return target == null ? null : _streamText(target);
  }
  final array = RegExp(r'/Contents\s*\[([^\]]*)\]').firstMatch(page.body);
  if (array == null) return null;
  final buffer = StringBuffer();
  for (final match in RegExp(r'(\d+)\s+0\s+R').allMatches(array.group(1)!)) {
    final target = byNumber[int.parse(match.group(1)!)];
    final text = target == null ? null : _streamText(target);
    if (text != null) buffer.write(text);
  }
  return buffer.toString();
}

bool _isDelimiter(String c) =>
    c == ' ' ||
    c == '\n' ||
    c == '\r' ||
    c == '\t' ||
    c == '\f' ||
    c == '(' ||
    c == ')' ||
    c == '<' ||
    c == '>' ||
    c == '[' ||
    c == ']' ||
    c == '{' ||
    c == '}' ||
    c == '/' ||
    c == '%';

final _operatorPattern = RegExp(r"[A-Za-z*'\x22]");

/// Walks a content stream and returns the visible text.
///
/// Operands do not survive an operator in a PDF content stream, so the operand
/// buffer is cleared after each operator. `Td`, `TD`, `T*` and `ET` become line
/// breaks so the extracted text keeps the document's reading order.
String _decodeContent(
  String content,
  Map<String, int> resourceToFont,
  Map<int, Map<int, String>> cmaps,
) {
  final out = StringBuffer();
  final operands = <Object>[];
  var font = '';
  var i = 0;

  while (i < content.length) {
    final c = content[i];

    if (c == '%') {
      while (i < content.length && content[i] != '\n') {
        i++;
      }
      continue;
    }

    if (c == '(') {
      final literal = _readLiteral(content, i);
      operands.add(_Literal(literal.value));
      i = literal.next;
      continue;
    }

    if (c == '<') {
      if (i + 1 < content.length && content[i + 1] == '<') {
        i += 2; // dictionary opening; irrelevant to text extraction
        continue;
      }
      final end = content.indexOf('>', i + 1);
      if (end < 0) break;
      operands.add(
        _Hex(content.substring(i + 1, end).replaceAll(RegExp(r'\s'), '')),
      );
      i = end + 1;
      continue;
    }

    if (c == '[') {
      final end = content.indexOf(']', i + 1);
      if (end < 0) break;
      operands.add(_Array(_stringsIn(content.substring(i + 1, end))));
      i = end + 1;
      continue;
    }

    if (c == '/') {
      var j = i + 1;
      while (j < content.length && !_isDelimiter(content[j])) {
        j++;
      }
      operands.add(_Name(content.substring(i + 1, j)));
      i = j;
      continue;
    }

    if (_operatorPattern.hasMatch(c)) {
      var j = i;
      while (j < content.length && _operatorPattern.hasMatch(content[j])) {
        j++;
      }
      final op = content.substring(i, j);
      i = j;
      switch (op) {
        case 'Tf':
          if (operands.length >= 2 && operands[operands.length - 2] is _Name) {
            font = (operands[operands.length - 2] as _Name).value;
          }
        case 'Tj':
          if (operands.isNotEmpty) {
            out.write(
              _decodeOperand(operands.last, font, resourceToFont, cmaps),
            );
          }
        case "'":
        case '"':
          out.write('\n');
          if (operands.isNotEmpty) {
            out.write(
              _decodeOperand(operands.last, font, resourceToFont, cmaps),
            );
          }
        case 'TJ':
          if (operands.isNotEmpty && operands.last is _Array) {
            for (final item in (operands.last as _Array).items) {
              out.write(_decodeOperand(item, font, resourceToFont, cmaps));
            }
          }
        case 'Td':
        case 'TD':
          // A pure horizontal move continues the line; a vertical move starts
          // a new one. This is what keeps the extracted text readable.
          out.write(_verticalDelta(operands) > 0.5 ? '\n' : ' ');
        case 'T*':
        case 'ET':
          out.write('\n');
      }
      operands.clear();
      continue;
    }

    if (c == '-' || c == '+' || c == '.' || RegExp(r'[0-9]').hasMatch(c)) {
      var j = i;
      while (j < content.length && RegExp(r'[-+.0-9]').hasMatch(content[j])) {
        j++;
      }
      operands.add(_Num(double.tryParse(content.substring(i, j)) ?? 0));
      i = j;
      continue;
    }

    i++;
  }

  return out.toString();
}

/// Magnitude of the vertical component of the last `Td`/`TD` operands.
double _verticalDelta(List<Object> operands) {
  final numbers = operands.whereType<_Num>().toList();
  if (numbers.length < 2) return 0;
  return numbers[numbers.length - 1].value.abs();
}

/// Reads a PDF literal string starting at the `(` index.
({String value, int next}) _readLiteral(String content, int start) {
  final buffer = StringBuffer();
  var i = start + 1;
  var depth = 1;
  while (i < content.length && depth > 0) {
    final ch = content[i];
    if (ch == '\\') {
      i++;
      if (i >= content.length) break;
      final esc = content[i];
      switch (esc) {
        case 'n':
          buffer.write('\n');
        case 'r':
          buffer.write('\r');
        case 't':
          buffer.write('\t');
        case 'b':
          buffer.write('\b');
        case 'f':
          buffer.write('\f');
        default:
          final code = esc.codeUnitAt(0);
          if (code >= 0x30 && code <= 0x37) {
            var oct = esc;
            var extra = 0;
            while (extra < 2 && i + 1 < content.length) {
              final nextCode = content[i + 1].codeUnitAt(0);
              if (nextCode >= 0x30 && nextCode <= 0x37) {
                oct += content[i + 1];
                i++;
                extra++;
              } else {
                break;
              }
            }
            buffer.writeCharCode(int.parse(oct, radix: 8));
          } else {
            buffer.write(esc);
          }
      }
      i++;
      continue;
    }
    if (ch == '(') {
      depth++;
      buffer.write(ch);
      i++;
      continue;
    }
    if (ch == ')') {
      depth--;
      if (depth > 0) buffer.write(ch);
      i++;
      continue;
    }
    buffer.write(ch);
    i++;
  }
  return (value: buffer.toString(), next: i);
}

List<Object> _stringsIn(String arrayBody) {
  final items = <Object>[];
  var i = 0;
  while (i < arrayBody.length) {
    final c = arrayBody[i];
    if (c == '(') {
      final literal = _readLiteral(arrayBody, i);
      items.add(_Literal(literal.value));
      i = literal.next;
      continue;
    }
    if (c == '<') {
      final end = arrayBody.indexOf('>', i + 1);
      if (end < 0) break;
      items.add(
        _Hex(arrayBody.substring(i + 1, end).replaceAll(RegExp(r'\s'), '')),
      );
      i = end + 1;
      continue;
    }
    i++;
  }
  return items;
}

String _decodeOperand(
  Object? operand,
  String font,
  Map<String, int> resourceToFont,
  Map<int, Map<int, String>> cmaps,
) {
  final cmap = cmaps[resourceToFont[font]];
  if (operand is _Literal) {
    if (cmap == null) return operand.value;
    final codes = operand.value.codeUnits;
    final buffer = StringBuffer();
    for (var i = 0; i + 1 < codes.length; i += 2) {
      final code = (codes[i] << 8) | codes[i + 1];
      buffer.write(cmap[code] ?? '');
    }
    return buffer.toString();
  }
  if (operand is _Hex) {
    final buffer = StringBuffer();
    if (cmap != null) {
      for (var i = 0; i + 4 <= operand.hex.length; i += 4) {
        final code = int.parse(operand.hex.substring(i, i + 4), radix: 16);
        buffer.write(cmap[code] ?? '');
      }
    } else {
      for (var i = 0; i + 2 <= operand.hex.length; i += 2) {
        buffer.writeCharCode(
          int.parse(operand.hex.substring(i, i + 2), radix: 16),
        );
      }
    }
    return buffer.toString();
  }
  return '';
}

/// Extracts the text from [bytes] with whitespace runs collapsed.
///
/// The parser returns the real code-point sequence written into the PDF; only
/// whitespace is normalised here, so content and reading-order assertions are
/// unaffected by how the PDF engine positioned each word.
String extractNormalisedPdfText(Uint8List bytes) =>
    extractPdfText(bytes).replaceAll(RegExp(r'\s+'), ' ').trim();

/// Counts the Arabic presentation forms (U+FB50–U+FEFF) in [text].
///
/// A non-zero count proves the shaped forms reached the PDF rather than the
/// unshaped base letters.
int countArabicPresentationForms(String text) {
  var count = 0;
  for (final code in text.codeUnits) {
    if (code >= 0xFB50 && code <= 0xFEFF) count++;
  }
  return count;
}
